import java.util.*;

class Solution {
  public Node moveSubTree(Node root, Node p, Node q) {
    Map<Node, Node> parent = new HashMap<>();
    fillParents(root, null, parent);
    if (parent.get(p) == q) return root; // already a direct child
    Node pParent = parent.get(p);
    if (inSubtree(p, q)) {
      // q lives under p: detach q, put it where p was, then hang p under q
      Node qParent = parent.get(q);
      qParent.children.remove(q);
      if (pParent == null) root = q;
      else pParent.children.set(pParent.children.indexOf(p), q);
    } else {
      pParent.children.remove(p);
    }
    q.children.add(p);
    return root;
  }

  private void fillParents(Node node, Node par, Map<Node, Node> parent) {
    parent.put(node, par);
    for (Node c : node.children) fillParents(c, node, parent);
  }

  private boolean inSubtree(Node top, Node target) {
    if (top == target) return true;
    for (Node c : top.children) if (inSubtree(c, target)) return true;
    return false;
  }
}
